={
  "model": "llama-3.1-8b-instant",
  "messages": [
    {
      "role": "system",
      "content": "You are a sentiment analysis engine for event feedback. Your job is to determine if an attendee is likely to return to future events based on their feedback.\n\nRules:\n- If the feedback indicates positive experience, satisfaction, enthusiasm, or likelihood of returning, output ONLY the single word: empath\n- If the feedback indicates dissatisfaction, complaints, unlikely to return, or negative experience, output ONLY the single word: needs growth\n- Do NOT output anything else. No explanation. No punctuation. Just one of the two phrases."
    },
    {
      "role": "user",
      "content": "Analyze this event feedback: \"{{ $json.Feedback }}\""
    }
  ],
  "temperature": 0.1,
  "max_tokens": 10
}
